catalog_script_client.script:
function onSubmit() {
    var ga = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMCoChairUtils');

    ga.addParam('sysparm_name', 'updateCoChairs');
    ga.addParam('sysparm_cmn_location_sys_id', g_form.getValue('building'));
    ga.addParam('sysparm_employee_co_chair', g_form.getValue('employee_co_chair'));
    ga.addParam('sysparm_employer_co_chair', g_form.getValue('employer_co_chair'));
    ga.addParam('sysparm_hs_representative', g_form.getValue('hs_representative'));
    ga.getXML(function(serverResponse) {
        var response = serverResponse.responseXML.documentElement.getAttribute("answer");

        g_form.addInfoMessage("The co-chairs update has been completed");
    });
}
